insert into public.categories (id, slug, name, short_name, name_ko, blurb, art, notes, is_visible, sort_order) values ('78b8e541-aab4-4c17-9aa7-d9f3ab0b76fe', 'signatures', 'Moba Signatures', 'Signatures', '모바 시그니처', 'Our two most-loved plates. Rabokki is ramyeon and tteokbokki simmered together in one pan, and the dish our kitchen is proudest of.', 'pot', '[{"title":"Ramyeon + tteokbokki = rabokki","ko":"라볶이","text":"Can’t choose between noodles and rice cakes? You don’t have to. Rabokki is Korea’s original ban-ban, half and half, simmered together in one sauce so every forkful gives you the slurp of ramyeon and the chew of tteok.","items":[]}]'::jsonb, true, 0);
