insert into public.category_addons (category_id, addon_id, sort_order) values ('78b8e541-aab4-4c17-9aa7-d9f3ab0b76fe', '4d05fb17-e3d5-4bf6-9204-616f2e776b51', 2);
insert into public.category_addons (category_id, addon_id, sort_order) values ('78b8e541-aab4-4c17-9aa7-d9f3ab0b76fe', '34c35f3f-1852-4000-aed5-8e9f4b694fbf', 3);
insert into public.categories (id, slug, name, short_name, name_ko, blurb, art, notes, is_visible, sort_order) values ('8d7ce6a1-b7aa-40e0-8127-359616e06759', 'starters', 'Korean Starters', 'Starters', '한국식 스타터', 'Crisp bites tossed to order in bold Korean sauces and finished with fresh veggies, the way Seoul does street food. Pick your base and we build the dish around it.', 'wok', '[{"title":"Choose your base","ko":"베이스 선택","text":"Cauliflower, potato or mushroom keeps a dish vegetarian. Chicken or meat makes it non-veg. Prawn dishes are served as they are.","items":[]},{"title":"Ban-ban, half & half","ko":"반반","text":"Can’t decide? Order any large starter as Ban-Ban for ₹149 extra and take two flavours in one plate. You can even pair a veg base with a non-veg one.","items":[]}]'::jsonb, true, 1);
insert into public.category_addons (category_id, addon_id, sort_order) values ('8d7ce6a1-b7aa-40e0-8127-359616e06759', 'fb12696f-d949-4dcb-bf94-b054412c13f7', 0);
insert into public.categories (id, slug, name, short_name, name_ko, blurb, art, notes, is_visible, sort_order) values ('8394f22a-ac5f-4f10-b4c0-4516bbcd68f8', 'crispy', 'Korean Crispy Bites', 'Crispy Bites', '바삭바삭', 'Fried fresh, sauced to order. Pick a size, then pick any flavour.', 'chicken', '[{"title":"Flavour options","ko":"소스 선택","text":"","items":[["Gochuchang","Authentic Korean chilli sauce with a bold and spicy kick and rich umami depth."],["Smoky Gochu","Bold Korean chilli sauce with smoky notes, balanced heat, and rich umami flavour."],["Topokki","Fiery blend of gochujang, garlic, and savoury seasonings with a hint of sweetness."],["Sweet Chilli","The perfect balance of sweetness and mild heat, finished with a delicious tangy kick."],["Bulgogi","A classic Korean BBQ sauce with a perfect balance of sweetness, soy, garlic, and sesame."],["Peri Peri Dusting","Zesty, smoky, and mildly spicy seasoning that adds a bold kick to every crispy bite."],["Buldak, extra hot","Fiery Korean chilli sauce packed with smoky heat, bold flavour, and addictive spice. Not for the faint-hearted!"],["Ban-ban (half n half)","Choose any two flavours. Available on large orders only."]]},{"title":"Make a meal","ko":"세트 메뉴","text":"Turn any plate into a full meal: add any one of fries, cold coffee, lemonade or lemon ice tea at ₹99.","items":[]}]'::jsonb, true, 2);
