insert into public.categories (id, slug, name, short_name, name_ko, blurb, art, notes, is_visible, sort_order) values ('b1ae8ce7-266a-4ba3-8672-1048f9550d52', 'mandu', 'Korean Mandu', 'Mandu', '만두', 'Hand-folded and steamed to order, then served your way. Five fillings, from garden-fresh vegetables to crystal-skin prawns.', 'dimsum', '[{"title":"Choose how it’s served","ko":"플레이팅 선택","text":"","items":[["Saucy plate","Perfectly steamed mandus plated over a velvety gochujang sauce with sautéed vegetables."],["Broth bowl","Steamed mandus served in a warming Korean broth infused with gochujang and vegetables."]]}]'::jsonb, true, 4);
insert into public.categories (id, slug, name, short_name, name_ko, blurb, art, notes, is_visible, sort_order) values ('b04ead45-0c6e-4f04-abc1-00dac33cbe4c', 'salads', 'Salads & Soups', 'Salads & Soups', '샐러드 · 국물', 'Fresh, light, comforting. Every salad and soup is made to order with your pick of chicken, fish, paneer or tofu.', 'soup', '[{"title":"Good to know","ko":"안내","text":"Salads are dressed to order, so they’re best eaten fresh. Soups are served hot in a shareable bowl. Ask for an extra bowl and we’ll split it for you. Paneer and tofu keep the dish fully vegetarian.","items":[]}]'::jsonb, true, 5);
