insert into public.categories (id, slug, name, short_name, name_ko, blurb, art, notes, is_visible, sort_order) values ('ca0a2349-0b90-406e-bc73-9b96e983b343', 'rameyon', 'Rameyon', 'Rameyon', '라면', 'Korean ramyeon built on a rich broth and springy noodles, finished with fresh vegetables and the filling you pick. Every bowl ₹339.', 'noodles', '[{"title":"Spice guide","ko":"맵기 단계","text":"Heat can be dialled up or down on any bowl. Just tell us when you order. Buldak is our hottest; approach with respect.","items":[]},{"title":"Choose your filling","ko":"토핑 선택","text":"Every rameyon comes with one filling of your choice at no extra cost. Tofu and paneer keep the bowl vegetarian.","items":[]}]'::jsonb, true, 7);
