insert into public.categories (id, slug, name, short_name, name_ko, blurb, art, notes, is_visible, sort_order) values ('9cdaa274-b012-4708-9a37-b2d91e192e07', 'toast', 'Toast, Melts & Burgers', 'Toast & Burgers', '토스트 · 버거', 'Korean flavours on continental classics. Pressed hot in our panini grill, then finished with gochujang, bulgogi, kimchi and buldak.', 'burger', '[{"title":"Made on panini bread","ko":"파니니","text":"Every toast and sandwich is built on panini bread and pressed hot to order: crisp ridged crust outside, melting centre inside. Never sourdough, never plain sliced bread.","items":[]}]'::jsonb, true, 9);
