insert into public.categories (id, slug, name, short_name, name_ko, blurb, art, notes, is_visible, sort_order) values ('2e9c473b-b31b-4e8c-9a02-07ac55625073', 'boba', 'Boba Bar', 'Boba Bar', '보바 · 버블티', 'Shaken to order, 39 ways to sip. Freshly brewed tea, fresh espresso, high-grade matcha and ube, real fruit and never syrup.', 'boba', '[{"title":"More boba? Always say yes.","ko":"토핑 추가","text":"Every cup comes with a generous scoop of pearls, but the regulars never stop at one. Feeling brave? Add coconut jelly too, and a scoop of ice cream on top.","items":[]}]'::jsonb, true, 10);
insert into public.category_groups (id, category_id, slug, name, name_ko, lede, sort_order) values ('17d39af0-59b9-4a72-bc01-e312c81e41c0', '2e9c473b-b31b-4e8c-9a02-07ac55625073', 'authentic', 'Authentic', '오리지널', 'Where boba began. Freshly brewed tea folded into creamy milk, then loaded with warm, chewy tapioca pearls.', 0);
insert into public.category_groups (id, category_id, slug, name, name_ko, lede, sort_order) values ('3fad8c96-cf3e-4713-947a-1825adf50e29', '2e9c473b-b31b-4e8c-9a02-07ac55625073', 'matcha', 'Matcha', '말차', 'High-grade matcha, whisked fresh so it stays vivid and grassy rather than bitter. Earthy, smooth and never dusty.', 1);
insert into public.category_groups (id, category_id, slug, name, name_ko, lede, sort_order) values ('c688412e-7bcf-45b0-a02c-1b2f7c2878d7', '2e9c473b-b31b-4e8c-9a02-07ac55625073', 'ube', 'Ube', '우베', 'High-grade purple yam, naturally sweet and nutty with that unmistakable violet colour. Our most photographed cup.', 2);
insert into public.category_groups (id, category_id, slug, name, name_ko, lede, sort_order) values ('b709f0e3-3e79-44fe-8264-f10f0011e2fd', '2e9c473b-b31b-4e8c-9a02-07ac55625073', 'chocolate', 'Chocolate', '초콜릿', 'Deep, proper cocoa, not powder and sugar. Rich enough to drink slowly, sweet enough to count as pudding.', 3);
insert into public.category_groups (id, category_id, slug, name, name_ko, lede, sort_order) values ('782199bc-3780-4672-aec1-a25d07366e69', '2e9c473b-b31b-4e8c-9a02-07ac55625073', 'coffee', 'Coffee', '커피', 'Freshly pulled espresso over ice, balanced with milk and pearls. The pick-me-up that chews back.', 4);
insert into public.category_groups (id, category_id, slug, name, name_ko, lede, sort_order) values ('997087e5-177e-4b18-8aab-58c1d81bd74e', '2e9c473b-b31b-4e8c-9a02-07ac55625073', 'coconut', 'Tender Coconut', '코코넛', 'Fresh tender coconut water and flesh, blended cold. Light, hydrating and quietly the most refreshing thing we make.', 5);
insert into public.category_groups (id, category_id, slug, name, name_ko, lede, sort_order) values ('972a3b79-e4b5-44e0-81f9-1f631b68d5fe', '2e9c473b-b31b-4e8c-9a02-07ac55625073', 'fruit', 'Fresh Fruit', '생과일', 'Real fruit, blended to order, never a syrup or a concentrate. What is in season is what tastes best.', 6);
insert into public.category_groups (id, category_id, slug, name, name_ko, lede, sort_order) values ('f7c3ec48-22e0-4c79-8d98-600030987047', '2e9c473b-b31b-4e8c-9a02-07ac55625073', 'banana', 'Banana', '바나나', 'Ripe bananas blended fresh for that thick, milkshake-soft body. Korea’s café favourite, four ways.', 7);
insert into public.category_groups (id, category_id, slug, name, name_ko, lede, sort_order) values ('78eda1f8-1742-4143-bfac-dbe617849a55', '2e9c473b-b31b-4e8c-9a02-07ac55625073', 'lemonade', 'Lemonade & Iced Tea', '레모네이드', 'Freshly brewed tea and real citrus over ice, the lightest way to drink boba. Sparkling options fizz.', 8);
insert into public.category_addons (category_id, addon_id, sort_order) values ('2e9c473b-b31b-4e8c-9a02-07ac55625073', '7e0b06a0-4814-4a67-88d3-a7dd4883dd99', 0);
